//! Teams' own emoticon catalog: the ids Teams uses for reactions and message emoticons
//! (`muscle`, `yes`, `cwl`, `1f389_partypopper`, ...), their skin-tone keys (`muscle-tone1`),
//! shortcuts (`(flex)`, `:D`) and names.
//!
//! The data is `data/teams-emoticons.tsv`, generated by `gen/teams.py` from the catalog the Teams
//! web client loads, and parsed once on first use.

use std::collections::HashMap;
use std::sync::LazyLock;

static TSV: &str = include_str!("../data/teams-emoticons.tsv");

/// Teams' named reactions; they win when several ids share a glyph (`like` over `yes` for 👍).
const PREFERRED: [&str; 6] = ["like", "heart", "laugh", "surprised", "sad", "angry"];

const ZWJ: char = '\u{200D}';
const VS16: char = '\u{FE0F}';
const HANDSHAKE: char = '\u{1F91D}';
const TONES: std::ops::RangeInclusive<char> = '\u{1F3FB}'..='\u{1F3FF}';

/// Unicode `Emoji_Modifier_Base` (emoji-data.txt 16.0): the codepoints a skin tone applies to.
const MODIFIER_BASES: [(u32, u32); 40] = [
    (0x261D, 0x261D),
    (0x26F9, 0x26F9),
    (0x270A, 0x270D),
    (0x1F385, 0x1F385),
    (0x1F3C2, 0x1F3C4),
    (0x1F3C7, 0x1F3C7),
    (0x1F3CA, 0x1F3CC),
    (0x1F442, 0x1F443),
    (0x1F446, 0x1F450),
    (0x1F466, 0x1F478),
    (0x1F47C, 0x1F47C),
    (0x1F481, 0x1F483),
    (0x1F485, 0x1F487),
    (0x1F48F, 0x1F48F),
    (0x1F491, 0x1F491),
    (0x1F4AA, 0x1F4AA),
    (0x1F574, 0x1F575),
    (0x1F57A, 0x1F57A),
    (0x1F590, 0x1F590),
    (0x1F595, 0x1F596),
    (0x1F645, 0x1F647),
    (0x1F64B, 0x1F64F),
    (0x1F6A3, 0x1F6A3),
    (0x1F6B4, 0x1F6B6),
    (0x1F6C0, 0x1F6C0),
    (0x1F6CC, 0x1F6CC),
    (0x1F90C, 0x1F90C),
    (0x1F90F, 0x1F90F),
    (0x1F918, 0x1F91F),
    (0x1F926, 0x1F926),
    (0x1F930, 0x1F939),
    (0x1F93C, 0x1F93E),
    (0x1F977, 0x1F977),
    (0x1F9B5, 0x1F9B6),
    (0x1F9B8, 0x1F9B9),
    (0x1F9BB, 0x1F9BB),
    (0x1F9CD, 0x1F9CF),
    (0x1F9D1, 0x1F9DD),
    (0x1FAC3, 0x1FAC5),
    (0x1FAF0, 0x1FAF8),
];

/// One emoticon of the Teams catalog.
#[derive(Debug, PartialEq, Eq)]
pub struct Emoticon {
    /// Teams' id: the reaction key and the `itemid` of a message emoticon.
    pub id: &'static str,
    /// The catalog's emoji (may carry U+FE0F). For a Teams-only animation, the closest emoji
    /// standing in for it, or empty when there is none.
    pub unicode: &'static str,
    /// Teams offers skin tones for it: its toned keys are `<id>-tone1` .. `<id>-tone5`.
    pub diverse: bool,
    /// An animation of Teams' own with no Unicode emoji.
    pub teams_only: bool,
    /// The catalog's English name ("Muscle").
    pub description: &'static str,
    shortcuts: &'static str,
    keywords: &'static str,
}

impl Emoticon {
    /// What typing turns into this emoticon: `(muscle)`, `(flex)`, `:D`, ...
    pub fn shortcuts(&self) -> impl Iterator<Item = &'static str> {
        self.shortcuts.split(' ').filter(|s| !s.is_empty())
    }

    /// Lowercase search words.
    pub fn keywords(&self) -> impl Iterator<Item = &'static str> {
        self.keywords.split(',').filter(|s| !s.is_empty())
    }

    /// What to show: the emoji with skin tone `tone` (1..=5; 0 is none), or the name of a
    /// Teams-only animation with no stand-in. Never the id.
    pub fn glyph(&self, tone: u8) -> String {
        if self.unicode.is_empty() {
            return self.description.to_string();
        }
        apply_tone(self.unicode, tone)
    }

    /// The reaction key Teams sends: `<id>-tone<n>` for a diverse emoticon and a tone, else `id`.
    pub fn key(&self, tone: u8) -> String {
        if self.diverse && (1..=5).contains(&tone) {
            format!("{}-tone{tone}", self.id)
        } else {
            self.id.to_string()
        }
    }

    /// The name for a hover card: "Muscle", or "Muscle: light skin tone" with a tone.
    pub fn name(&self, tone: u8) -> String {
        match tone_name(tone) {
            Some(t) => format!("{}: {t} skin tone", self.description),
            None => self.description.to_string(),
        }
    }
}

struct Catalog {
    all: Vec<Emoticon>,
    by_id: HashMap<&'static str, usize>,
    by_shortcut: HashMap<String, usize>,
    by_glyph: HashMap<String, Vec<usize>>,
}

static CATALOG: LazyLock<Catalog> = LazyLock::new(|| {
    let all: Vec<Emoticon> = TSV
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|l| {
            let mut f = l.split('\t');
            let id = f.next().filter(|s| !s.is_empty())?;
            let unicode = f.next()?;
            let flags = f.next()?;
            Some(Emoticon {
                id,
                unicode,
                diverse: flags.contains('d'),
                teams_only: flags.contains('t'),
                description: f.next()?,
                shortcuts: f.next().unwrap_or_default(),
                keywords: f.next().unwrap_or_default(),
            })
        })
        .collect();
    let mut by_id = HashMap::new();
    let mut by_shortcut = HashMap::new();
    let mut by_glyph: HashMap<String, Vec<usize>> = HashMap::new();
    for (i, e) in all.iter().enumerate() {
        by_id.entry(e.id).or_insert(i);
        for s in e.shortcuts() {
            by_shortcut.entry(s.to_lowercase()).or_insert(i);
        }
        if !e.teams_only && !e.unicode.is_empty() {
            by_glyph.entry(bare(e.unicode)).or_default().push(i);
        }
    }
    Catalog {
        all,
        by_id,
        by_shortcut,
        by_glyph,
    }
});

/// `s` without U+FE0F and skin-tone modifiers.
fn bare(s: &str) -> String {
    s.chars()
        .filter(|c| *c != VS16 && !TONES.contains(c))
        .collect()
}

/// Every emoticon, in Teams' picker order (category, then catalog order).
pub fn all() -> &'static [Emoticon] {
    &CATALOG.all
}

/// The emoticon with Teams id `id` (case-insensitive).
pub fn by_id(id: &str) -> Option<&'static Emoticon> {
    let c = &*CATALOG;
    c.by_id
        .get(id)
        .or_else(|| c.by_id.get(id.to_lowercase().as_str()))
        .map(|i| &c.all[*i])
}

/// The emoticon a shortcut stands for: `(muscle)`, `(FLEX)`, `:D` ... (case-insensitive).
pub fn by_shortcut(shortcut: &str) -> Option<&'static Emoticon> {
    let c = &*CATALOG;
    c.by_shortcut
        .get(&shortcut.trim().to_lowercase())
        .map(|i| &c.all[*i])
}

/// A key's id and skin tone: `muscle-tone1` is (`muscle`, 1), `muscle` is (`muscle`, 0).
/// A suffix that is not `-tone1`..`-tone5` stays part of the id.
pub fn split_tone(key: &str) -> (&str, u8) {
    if let Some((base, n)) = key.rsplit_once("-tone")
        && let Ok(t) = n.parse::<u8>()
        && (1..=5).contains(&t)
        && !base.is_empty()
    {
        return (base, t);
    }
    (key, 0)
}

/// The emoticon and tone of a reaction key (`muscle-tone1`, `cwl`, `1f389_partypopper`).
pub fn parse_key(key: &str) -> Option<(&'static Emoticon, u8)> {
    let (id, tone) = split_tone(key.trim());
    by_id(id).map(|e| (e, tone))
}

/// What a reaction key shows: `muscle-tone1` is 💪🏻.
pub fn glyph_of_key(key: &str) -> Option<String> {
    parse_key(key).map(|(e, t)| e.glyph(t))
}

/// A reaction key's hover-card name: `muscle-tone1` is "Muscle: light skin tone".
pub fn name_of_key(key: &str) -> Option<String> {
    parse_key(key).map(|(e, t)| e.name(t))
}

/// The key Teams sends for an emoji: 👍 is `like`, 👍🏼 is `yes-tone2` (the diverse id),
/// 🔥 is `fire`. None for an emoji the catalog lacks (flags, ...).
pub fn key_for_glyph(glyph: &str) -> Option<String> {
    let c = &*CATALOG;
    let tone = glyph
        .chars()
        .find(|ch| TONES.contains(ch))
        .map_or(0, |ch| (ch as u32 - 0x1F3FA) as u8);
    let hits = c.by_glyph.get(&bare(glyph))?;
    let pick = move |i: &usize| -> &'static Emoticon { &c.all[*i] };
    if tone > 0 {
        return hits
            .iter()
            .map(pick)
            .find(|e| e.diverse)
            .map(|e| e.key(tone));
    }
    hits.iter()
        .map(pick)
        .find(|e| PREFERRED.contains(&e.id))
        .or_else(|| hits.first().map(pick))
        .map(|e| e.id.to_string())
}

/// Case-insensitive search, best first: exact id or shortcut (with or without its brackets),
/// then id or name starting with `q`, then a shortcut, name word or keyword starting with it,
/// then substrings. Ties keep catalog order. An empty query finds nothing.
pub fn search(q: &str, limit: usize) -> Vec<&'static Emoticon> {
    let q = q.trim().to_lowercase();
    if q.is_empty() || limit == 0 {
        return Vec::new();
    }
    let mut hits: Vec<(u8, &'static Emoticon)> = all()
        .iter()
        .filter_map(|e| rank(e, &q).map(|t| (t, e)))
        .collect();
    hits.sort_by_key(|(t, _)| *t);
    hits.into_iter().take(limit).map(|(_, e)| e).collect()
}

fn rank(e: &Emoticon, q: &str) -> Option<u8> {
    let shortcuts: Vec<String> = e.shortcuts().map(str::to_lowercase).collect();
    let unbracketed =
        |s: &String| -> String { s.trim_start_matches('(').trim_end_matches(')').to_string() };
    if e.id == q || shortcuts.iter().any(|s| *s == q || unbracketed(s) == q) {
        return Some(0);
    }
    let name = e.description.to_lowercase();
    if e.id.starts_with(q) || name.starts_with(q) {
        return Some(1);
    }
    let prefix = shortcuts.iter().any(|s| unbracketed(s).starts_with(q))
        || name
            .split(|c: char| !c.is_alphanumeric())
            .any(|w| w.starts_with(q))
        || e.keywords().any(|k| k.starts_with(q));
    if prefix {
        return Some(2);
    }
    (name.contains(q) || e.id.contains(q) || e.keywords().any(|k| k.contains(q))).then_some(3)
}

fn is_modifier_base(c: char) -> bool {
    let c = c as u32;
    MODIFIER_BASES.iter().any(|(a, b)| (*a..=*b).contains(&c))
}

/// `glyph` with skin tone `tone` (1..=5, light to dark; anything else leaves it as is). Every
/// person or hand in it gets the modifier, a following U+FE0F is dropped, and the handshake
/// joining two people (🧑‍🤝‍🧑) stays untoned, as Unicode spells these sequences.
pub fn apply_tone(glyph: &str, tone: u8) -> String {
    let Some(modifier) = (1..=5)
        .contains(&tone)
        .then(|| char::from_u32(0x1F3FA + u32::from(tone)))
        .flatten()
    else {
        return glyph.to_string();
    };
    let mut out = String::with_capacity(glyph.len() + 8);
    let mut chars = glyph.chars().peekable();
    let mut prev = None;
    while let Some(c) = chars.next() {
        out.push(c);
        let joined_handshake = c == HANDSHAKE && prev == Some(ZWJ);
        if is_modifier_base(c)
            && !joined_handshake
            && !chars.peek().is_some_and(|n| TONES.contains(n))
        {
            out.push(modifier);
            if chars.peek() == Some(&VS16) {
                chars.next();
            }
        }
        prev = Some(c);
    }
    out
}

/// "light", "medium-light", "medium", "medium-dark" or "dark" for tones 1..=5.
pub fn tone_name(tone: u8) -> Option<&'static str> {
    match tone {
        1 => Some("light"),
        2 => Some("medium-light"),
        3 => Some("medium"),
        4 => Some("medium-dark"),
        5 => Some("dark"),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_whole_catalog_is_loaded() {
        assert!(all().len() > 1600, "only {} emoticons", all().len());
        assert!(all().iter().filter(|e| e.diverse).count() > 250);
        assert!(all().iter().all(|e| !e.id.is_empty()));
    }

    #[test]
    fn toned_keys_decode_with_the_fitzpatrick_modifier() {
        assert_eq!(glyph_of_key("muscle").as_deref(), Some("💪"));
        assert_eq!(glyph_of_key("muscle-tone1").as_deref(), Some("💪🏻"));
        assert_eq!(glyph_of_key("muscle-tone5").as_deref(), Some("💪🏿"));
        assert_eq!(glyph_of_key("yes-tone2").as_deref(), Some("👍🏼"));
        assert_eq!(glyph_of_key("cwl").as_deref(), Some("😂"));
        assert_eq!(glyph_of_key("nosuchthing"), None);
    }

    #[test]
    fn a_zwj_sequence_takes_the_tone_on_its_person_and_drops_vs16() {
        // Man facepalming: 🤦 ZWJ ♂ FE0F -> 🤦🏽 ZWJ ♂ FE0F.
        assert_eq!(
            glyph_of_key("manfacepalming-tone3").as_deref(),
            Some("\u{1F926}\u{1F3FD}\u{200D}\u{2642}\u{FE0F}")
        );
        // Both fists of the fist bump.
        assert_eq!(
            glyph_of_key("fistbump-tone4").as_deref(),
            Some("\u{1F91C}\u{1F3FE}\u{1F91B}\u{1F3FE}")
        );
        // Victory hand: the modifier replaces U+FE0F.
        assert_eq!(apply_tone("\u{270C}\u{FE0F}", 1), "\u{270C}\u{1F3FB}");
        // People holding hands: both people, not the handshake between them.
        assert_eq!(
            apply_tone("\u{1F9D1}\u{200D}\u{1F91D}\u{200D}\u{1F9D1}", 2),
            "\u{1F9D1}\u{1F3FC}\u{200D}\u{1F91D}\u{200D}\u{1F9D1}\u{1F3FC}"
        );
        // A standalone handshake takes it; something with no person stays as is.
        assert_eq!(apply_tone("\u{1F91D}", 5), "\u{1F91D}\u{1F3FF}");
        assert_eq!(apply_tone("🔥", 3), "🔥");
        assert_eq!(apply_tone("💪", 0), "💪");
        assert_eq!(apply_tone("💪", 6), "💪");
    }

    #[test]
    fn teams_only_animations_show_a_stand_in_never_the_id() {
        let oreo = by_id("oreo").unwrap();
        assert!(oreo.teams_only);
        assert_eq!(oreo.glyph(0), "🍪");
        let support = glyph_of_key("support-tone2").unwrap();
        assert!(!support.contains("support") && !support.contains('('));
        for e in all() {
            assert!(
                !e.glyph(0).starts_with('('),
                "{} shows {}",
                e.id,
                e.glyph(0)
            );
            assert!(!e.glyph(0).is_empty(), "{} shows nothing", e.id);
        }
    }

    #[test]
    fn names_carry_the_skin_tone() {
        assert_eq!(name_of_key("muscle").as_deref(), Some("Muscle"));
        assert_eq!(
            name_of_key("muscle-tone1").as_deref(),
            Some("Muscle: light skin tone")
        );
        assert_eq!(
            name_of_key("yes-tone4").as_deref(),
            Some("Yes: medium-dark skin tone")
        );
    }

    #[test]
    fn split_tone_only_takes_tones_one_to_five() {
        assert_eq!(split_tone("muscle-tone1"), ("muscle", 1));
        assert_eq!(split_tone("muscle"), ("muscle", 0));
        assert_eq!(split_tone("muscle-tone9"), ("muscle-tone9", 0));
        assert_eq!(split_tone("-tone2"), ("-tone2", 0));
    }

    #[test]
    fn keys_for_glyphs_follow_teams() {
        assert_eq!(key_for_glyph("👍").as_deref(), Some("like"));
        assert_eq!(key_for_glyph("👍🏼").as_deref(), Some("yes-tone2"));
        assert_eq!(key_for_glyph("❤").as_deref(), Some("heart"));
        assert_eq!(key_for_glyph("🔥").as_deref(), Some("fire"));
        assert_eq!(key_for_glyph("💪🏻").as_deref(), Some("muscle-tone1"));
        assert_eq!(key_for_glyph("🇪🇬"), None);
        let muscle = by_id("muscle").unwrap();
        assert_eq!(muscle.key(3), "muscle-tone3");
        assert_eq!(
            by_id("fire").unwrap().key(3),
            "fire",
            "no tones on a non-diverse id"
        );
    }

    #[test]
    fn shortcuts_find_their_emoticon() {
        assert_eq!(by_shortcut("(muscle)").unwrap().id, "muscle");
        assert_eq!(by_shortcut("(FLEX)").unwrap().id, "muscle");
        assert_eq!(by_shortcut("(y)").unwrap().id, "yes");
        assert!(by_shortcut("(nosuchthing)").is_none());
    }

    #[test]
    fn search_matches_ids_shortcuts_names_and_keywords() {
        assert_eq!(
            search("flex", 5)[0].id,
            "muscle",
            "shortcut without brackets"
        );
        assert_eq!(search("(flex)", 5)[0].id, "muscle", "shortcut as typed");
        assert_eq!(search("cwl", 5)[0].id, "cwl");
        assert_eq!(search("heart", 5)[0].id, "heart");
        assert!(search("crying with", 10).iter().any(|e| e.id == "cwl"));
        assert!(
            search("biceps", 10).iter().any(|e| e.id == "muscle"),
            "keyword"
        );
        assert!(search("zzzzqqq", 10).is_empty());
        assert!(search("  ", 10).is_empty());
        assert_eq!(search("smile", 3).len(), 3);
    }
}
